<?php
require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','receptionist','accountant']);$bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='add'){$member=(int)$_POST['member_id'];$amount=(float)$_POST['amount'];$ref=trim($_POST['reference_no']??'')?:'PAY-'.date('ymdHis');db()->prepare("INSERT INTO payments(branch_id,member_id,amount,method,payment_type,reference_no,payment_date,status,note,created_by) VALUES(?,?,?,?,?,?,?, 'paid',?,?)")->execute([$bid,$member,$amount,$_POST['method'],$_POST['payment_type'],$ref,$_POST['payment_date'],trim($_POST['note']??''),user()['id']]);$id=(int)db()->lastInsertId();audit_log('payment.created','payment',$id,$ref.' · '.money($amount));flash('success','Payment recorded successfully.');redirect('app/payment_receipt.php?id='.$id);}}
$rows=query_all("SELECT p.*,m.member_code,CONCAT(m.first_name,' ',m.last_name) member_name FROM payments p JOIN members m ON m.id=p.member_id WHERE p.branch_id=? ORDER BY p.payment_date DESC,p.id DESC LIMIT 150",[$bid]);$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? ORDER BY first_name",[$bid]);$month=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE branch_id=? AND status='paid' AND payment_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);$today=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE branch_id=? AND status='paid' AND payment_date=CURDATE()",[$bid]);$pt=(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE branch_id=? AND status='paid' AND payment_type='Personal Training' AND payment_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);
$pageTitle='Payments & Billing';include __DIR__.'/../includes/header.php'; ?>
<div class="metric-strip"><div class="metric-box"><small>This month</small><strong><?= money($month) ?></strong></div><div class="metric-box"><small>Collected today</small><strong><?= money($today) ?></strong></div><div class="metric-box"><small>PT revenue this month</small><strong><?= money($pt) ?></strong></div><div class="metric-box"><small>Transactions shown</small><strong><?= count($rows) ?></strong></div></div><div class="page-actions"><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#paymentModal"><i class="fa-solid fa-plus me-2"></i>Record payment</button></div>
<div class="table-card"><div class="table-toolbar"><div><strong>Transaction ledger</strong><div class="text-muted" style="font-size:.68rem">Memberships, PT and other collections</div></div><a class="btn btn-dark btn-sm" href="<?= url('app/reports.php?export=payments') ?>"><i class="fa-solid fa-file-export me-1"></i>Export CSV</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Member</th><th>Type</th><th>Method</th><th>Date</th><th>Amount</th><th>Status</th><th class="text-end">Receipt</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['reference_no']) ?></td><td><div class="member-cell"><div class="avatar"><?= e(initials($r['member_name'])) ?></div><div><strong><?= e($r['member_name']) ?></strong><small><?= e($r['member_code']) ?></small></div></div></td><td><?= e($r['payment_type']) ?></td><td><?= e($r['method']) ?></td><td><?= format_date($r['payment_date']) ?></td><td><strong><?= money($r['amount']) ?></strong></td><td><span class="badge-soft badge-<?= status_badge($r['status']) ?>"><?= e(ucfirst($r['status'])) ?></span></td><td class="text-end"><a class="action-btn" href="<?= url('app/payment_receipt.php?id='.$r['id']) ?>" title="Open receipt"><i class="fa-solid fa-receipt"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="modal fade" id="paymentModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="add"><div class="modal-header"><h5>Record payment</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="form-label">Member</label><select name="member_id" class="form-select" required><?php foreach($members as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['member_code'].' — '.$m['name']) ?></option><?php endforeach; ?></select></div><div class="col-6"><label class="form-label">Amount</label><input type="number" step=".01" name="amount" class="form-control" required></div><div class="col-6"><label class="form-label">Date</label><input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" class="form-control" required></div><div class="col-6"><label class="form-label">Payment type</label><select name="payment_type" class="form-select"><option>Membership</option><option>Personal Training</option><option>Class</option><option>Product</option><option>Other</option></select></div><div class="col-6"><label class="form-label">Method</label><select name="method" class="form-select"><option>Cash</option><option>Card</option><option>Bank</option><option>Mobile Banking</option></select></div><div class="col-12"><label class="form-label">Reference (optional)</label><input name="reference_no" class="form-control"></div><div class="col-12"><label class="form-label">Note</label><input name="note" class="form-control"></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save payment & open receipt</button></div></form></div></div></div>
